    26|      --orange: #f97316;
    27|      --info: #06b6d4;
    28|      --purple: #8b5cf6;
    29|      --sidebar-w: 220px;
    30|      --shadow: 0 4px 24px rgba(0,0,0,0.3);
    31|    }
    32|    html { scroll-behavior: smooth; }
