    .ops-card .oc-status-dot.yellow{background:#f59e0b;box-shadow:0 0 6px rgba(245,158,11,.5)}
    .ops-card .oc-status-dot.red{background:#ef4444;box-shadow:0 0 6px rgba(239,68,68,.5)}
    .ops-card .oc-progress{margin-top:2px}
    .ops-card .oc-progress-bar{height:6px;background:#1e293b;border-radius:3px;overflow:hidden;border:1px solid #334155}
    .ops-card .oc-progress-fill{height:100%;border-radius:3px;transition:width .5s ease}
    .ops-card .oc-progress-fill.green{background:linear-gradient(90deg,#22c55e,#16a34a)}
