function renderOps() {
  const grid = document.getElementById('opsGrid');
  if (!grid) return;
  grid.innerHTML = pipelinesData.map(p => {
    const pct = p.pct;
    const stageLabel = `${p.currentStage}/${p.stages.length}`;
    const statusLabel = { running:'▶ Running', paused:'⏸ Paused', stopped:'■ Stopped' }[p.status] || p.status;
    const btnActive = (b) => p.status === b ? 'btn-active' : '';
    return `<div class="ops-card">
      <div class="oc-header">
        <div class="oc-icon-name">
          <span class="oc-icon">${p.icon}</span>
          <span class="oc-name">${p.name}</span>
        </div>
        <div class="oc-controls">
          <button class="btn btn-run ${btnActive('running')}" onclick="opsRun('${p.id}')" title="Run">▶</button>
          <button class="btn btn-pause ${btnActive('paused')}" onclick="opsPause('${p.id}')" title="Pause">⏸</button>
          <button class="btn btn-stop ${btnActive('stopped')}" onclick="opsStop('${p.id}')" title="Stop">■</button>
        </div>
      </div>
      <div class="oc-health"><span class="oc-status-dot ${p.health}"></span> ${statusLabel} · Stage ${stageLabel}</div>
